arguments.query:
SELECT time, pid, ppid, process_name, command_line, netconn_domain, remote_ip, remote_port
FROM audit_logs
WHERE (process_name LIKE '%payload.exe%' OR ppid IN (
  SELECT pid FROM audit_logs WHERE process_name LIKE '%payload.exe%'
)) AND (netconn_domain IS NOT NULL OR remote_ip IS NOT NULL OR remote_port IS NOT NULL)
ORDER BY time;

SELECT time, pid, ppid, process_name, command_line, netconn_domain, remote_ip, remote_port
FROM audit_logs
WHERE (process_name LIKE '%payload.exe%' OR ppid IN (
  SELECT pid FROM audit_logs WHERE process_name LIKE '%payload.exe%'
)) AND (netconn_domain IS NOT NULL OR remote_ip IS NOT NULL OR remote_port IS NOT NULL)
ORDER BY time;

SELECT time, pid, ppid, process_name, command_line, access, object
FROM audit_logs
WHERE (process_name LIKE '%payload.exe%' OR ppid IN (
  SELECT pid FROM audit_logs WHERE process_name LIKE '%payload.exe%'
)) AND access IN ('write', 'read', 'delete')
ORDER BY time;

